-- Three forms of a counted noun, chosen by the first number shown:
-- 1 день, 2 дня, 5 дней. The core asks for a form only when an entry is a
-- table of three.
function language.forms(n)
  n = math.abs(tonumber(n) or 0)
  local mod100, mod10 = n % 100, n % 10
  if mod100 >= 11 and mod100 <= 14 then return 3 end
  if mod10 == 1 then return 1 end
  if mod10 >= 2 and mod10 <= 4 then return 2 end
  return 3
end

for english, translated in pairs(language.strings) do
  if type(translated) == "string" then
    language.upper[string.upper(english)] = translated
  end
end
ns.RegisterLocale("ruRU", language)
